import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"合同审查工作流","description":"项目契约：使用 LangGraph 实现可并行检查、人工复核、暂停恢复和失败重试的合同审查流程。","frontmatter":{"title":"合同审查工作流","description":"项目契约：使用 LangGraph 实现可并行检查、人工复核、暂停恢复和失败重试的合同审查流程。","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"py-agent/architecture/projects/contract-review-workflow.md","filePath":"py-agent/architecture/projects/contract-review-workflow.md","lastUpdated":null}'),i={name:"py-agent/architecture/projects/contract-review-workflow.md"};function l(c,e,n,p,s,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="合同审查工作流" tabindex="-1">合同审查工作流 <a class="header-anchor" href="#合同审查工作流" aria-label="Permalink to &quot;合同审查工作流&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本项目类型为 <strong>持久化工作流</strong>。合同审查具有固定阶段、明确责任和人工签字点，因此使用 LangGraph 表达状态和恢复语义，而不是交给开放式 Agent 自由规划。</p><h2 id="项目结果" tabindex="-1">项目结果 <a class="header-anchor" href="#项目结果" aria-label="Permalink to &quot;项目结果&quot;">​</a></h2><p>读者最终会得到一个异步合同审查服务：上传合同后生成任务，解析基础字段，并行执行条款缺失、金额、期限和合规风险检查，汇总结果后等待法务复核，人工修改或批准后生成审查报告。</p><h2 id="实现范围" tabindex="-1">实现范围 <a class="header-anchor" href="#实现范围" aria-label="Permalink to &quot;实现范围&quot;">​</a></h2><ul><li>LangGraph StateGraph 定义解析、并行检查、汇总、人工复核和发布节点；</li><li>PostgreSQL Checkpointer 保存线程状态和恢复位置；</li><li>PostgreSQL 业务表保存合同、审查任务、人工决定和报告版本；</li><li>对象存储保存原文件和最终报告，后台 Worker 执行长任务；</li><li><code>interrupt()</code> 与 <code>Command</code> 实现人工复核和恢复；</li><li>节点使用幂等键、有限重试和补偿避免重复发布；</li><li>测试覆盖并行汇总、进程重启、重复恢复、人工驳回和节点失败。</li></ul><h2 id="验收基线" tabindex="-1">验收基线 <a class="header-anchor" href="#验收基线" aria-label="Permalink to &quot;验收基线&quot;">​</a></h2><p>项目必须用状态历史证明暂停前后的执行连续性，并验证 Worker 崩溃后不会重复生成报告。电子签章、复杂 OCR 和法律结论自动化不属于项目范围。</p>',9)])])}const _=a(i,[["render",l]]);export{u as __pageData,_ as default};
